// The bundled alert sounds (HANDOFF §5 "Sounds"). The files are generated by
// tools/sounds/generate_sounds.py into Resources/Sounds/ and copied flat into the app bundle root
// (PROGRESS.md D13), which is where UNNotificationSound looks for them.

/// One of the bundled alert sounds. The raw value is what settings store.
public enum AlertSoundID: String, Sendable, Equatable, Hashable, Codable, CaseIterable {
    case cascade
    case tide
    case dusk
    case summit
    case swoop
    case sonar
    case doorbell
    case warble
}

/// A bundled sound as the Alerts screen shows it.
public struct AlertSoundInfo: Sendable, Equatable, Identifiable {
    public let id: AlertSoundID
    /// File name in the app bundle root, with extension (e.g. `alert-cascade.wav`).
    public let fileName: String
    public let displayName: String
    /// What it sounds like, for the sound picker.
    public let character: String
    /// The alerts that use this sound unless the user picks another.
    public let defaultFor: [AlertKind]
}

/// The catalog of bundled sounds and each alert's default. Every alert family has its own default
/// sound so the families can be told apart by ear; alerts that share a sound share a meaning
/// (all sensor-lifecycle notices share one, all faults share one).
public enum AlertSoundCatalog {
    /// All sounds, in picker order.
    public static let all: [AlertSoundInfo] = AlertSoundID.allCases.map(info)

    public static func info(_ id: AlertSoundID) -> AlertSoundInfo {
        AlertSoundInfo(
            id: id,
            fileName: fileName(id),
            displayName: displayName(id),
            character: character(id),
            defaultFor: AlertKind.allCases.filter { defaultSound(for: $0) == id }
        )
    }

    /// The file in the app bundle root used for notifications and the in-app sound: linear PCM
    /// WAV. Must match tools/sounds/generate_sounds.py `SOUNDS`.
    public static func fileName(_ id: AlertSoundID) -> String {
        "alert-\(id.rawValue).wav"
    }

    /// The same sound as an IMA4 CAF, for AlarmKit system alarms (D26). Loop verified on hardware
    /// that AlarmKit plays bundled IMA4 `.caf` files by name (LoopKit/Loop PR #2520); WAV is not
    /// verified for AlarmKit, so alarms use this variant. Generated by the same script.
    public static func alarmFileName(_ id: AlertSoundID) -> String {
        "alert-\(id.rawValue).caf"
    }

    public static func displayName(_ id: AlertSoundID) -> String {
        switch id {
        case .cascade: return "Cascade"
        case .tide: return "Tide"
        case .dusk: return "Dusk"
        case .summit: return "Summit"
        case .swoop: return "Swoop"
        case .sonar: return "Sonar"
        case .doorbell: return "Doorbell"
        case .warble: return "Warble"
        }
    }

    public static func character(_ id: AlertSoundID) -> String {
        switch id {
        case .cascade: return "Fast falling four-note bursts, repeated. The most insistent."
        case .tide: return "Slow falling two-note swell, twice."
        case .dusk: return "Three soft descending wooden notes."
        case .summit: return "Three bright ascending bell notes."
        case .swoop: return "A rising-then-falling glide, twice."
        case .sonar: return "A single ping with an echo, repeated once."
        case .doorbell: return "A two-note ding-dong."
        case .warble: return "A low two-tone trill in three bursts."
        }
    }

    /// The default sound for each alert.
    public static func defaultSound(for kind: AlertKind) -> AlertSoundID {
        switch kind {
        case .urgentLow: return .cascade
        case .urgentLowSoon: return .tide
        case .low: return .dusk
        case .high: return .summit
        case .fallingFast, .risingFast: return .swoop
        case .missedReadings: return .sonar
        case .sensorWarmUpComplete, .sensorExpiringIn24Hours, .sensorExpiringIn2Hours, .sensorGracePeriod:
            return .doorbell
        case .sensorFailed, .sensorError, .calibrationNeeded, .sensorExpired, .bluetoothUnavailable, .trioBridge:
            return .warble
        }
    }
}
